<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">远程组件</p>
      <h1 class="demo-page__title">comps-vue3 · BilibiliBanner</h1>
      <p class="demo-page__lead">
        从 bilibili-banner-master 的 Vue 版本迁移来的 B 站节日横幅：23 套主题，每套由多层图片 / 视频叠成，
        每层按各自的 bench 系数跟手，指针在横幅上左右移动就会错位出视差；触摸端点一下左上角 logo 复位。
        图层资源随 comps-vue3 的 public/bilibili 一起下发，远程加载时会自动指到远端包的地址。
      </p>
    </header>

    <section class="bb-demo">
      <div class="bb-demo__head">
        <h2 class="demo-page__section-title">主题</h2>
        <code class="bb-demo__tag">{{ currentLabel }}</code>
      </div>

      <div class="bb-demo__themes">
        <button
          v-for="item in THEMES"
          :key="item.value"
          type="button"
          class="bb-demo__theme"
          :class="{ 'is-active': item.value === theme }"
          @click="theme = item.value"
        >
          {{ item.label }}
        </button>
      </div>

      <div class="bb-demo__stage">
        <BilibiliBanner :theme="theme" :height="180" />
      </div>
      <p class="bb-demo__hint">
        把指针放到横幅上左右移动（或横向滑动）试试；换成主题时图层会重新铺开。
      </p>

      <div class="bb-demo__row">
        <div class="bb-demo__cell">
          <BilibiliBanner theme="winter-1" :height="120" :logo="false" />
          <p><code>:logo="false"</code> 去掉左上角 logo，单独看图层</p>
        </div>
        <div class="bb-demo__cell">
          <BilibiliBanner theme="summer-5" :height="120" background="#101820" />
          <p><code>background</code> 是图层没铺满时的底色</p>
        </div>
      </div>
    </section>

    <DemoPreview class="bb-preview">
      <LevaPlayground
        name="BilibiliBanner"
        :component="BilibiliBanner"
        :schema="BilibiliBannerSchema"
        :stage-style="stageStyle"
      />
    </DemoPreview>

    <p class="demo-note">
      <span>
        属性面板里 <code>theme</code> 是 23 套主题的下拉，<code>height</code> 是横幅高度，
        <code>logo</code> 控制左上角 logo，<code>background</code> 是兜底底色；
        远程包会把 <code>public/bilibili/&lt;theme&gt;/</code> 里的图层按绝对地址加载。
      </span>
    </p>
  </div>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue'
import BilibiliBannerSchema from '@melt-js/comps-vue3/src/components/BilibiliBanner/propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { remoteComponent } from '../configs/remote'

const BilibiliBanner = remoteComponent('BilibiliBanner')

/** 与原仓库 inst 组件一一对应的主题名，顺序按春 → 夏 → 秋 → 冬 */
const THEMES = [
  { value: 'spring-1', label: '春日 1' },
  { value: 'spring-2', label: '春日 2' },
  { value: 'spring-3', label: '春日 3' },
  { value: 'spring-4', label: '春日 4' },
  { value: 'spring-5', label: '春日 5' },
  { value: 'spring-6', label: '春日 6' },
  { value: 'summer-1', label: '夏日 1' },
  { value: 'summer-2', label: '夏日 2' },
  { value: 'summer-3', label: '夏日 3' },
  { value: 'summer-4', label: '夏日 4' },
  { value: 'summer-5', label: '夏日 5' },
  { value: 'summer-6', label: '夏日 6' },
  { value: 'summer-7', label: '夏日 7' },
  { value: 'autumn-1', label: '秋日 1' },
  { value: 'autumn-2', label: '秋日 2' },
  { value: 'autumn-3', label: '秋日 3' },
  { value: 'autumn-4', label: '秋日 4' },
  { value: 'autumn-5', label: '秋日 5' },
  { value: 'winter-1', label: '冬日 1' },
  { value: 'winter-2', label: '冬日 2' },
  { value: 'winter-3', label: '冬日 3' },
  { value: 'winter-4', label: '冬日 4' },
  { value: 'winter-5', label: '冬日 5' },
] as const

type BannerTheme = (typeof THEMES)[number]['value']

const theme = ref<BannerTheme>('spring-1')
const currentLabel = computed(() => THEMES.find((item) => item.value === theme.value)?.label ?? '')

const stageStyle = {
  display: 'block',
  height: '210px',
  padding: '12px',
  background: '#eef1f5',
}
</script>

